  // instance label. Do not duplicate it as a default ally during preparation.
  const named=Object.values(w.actors).filter(a=>!a.mergedInto&&names(a).some(n=>normalize(n)===normalize(input.name)));
  if(named.length===1&&(named[0].kind!=='enemy'||w.meta?.native?.actors?.[named[0].id]?.instanceKey||w.combat?.order.some(r=>r.actorId===named[0].id)))return named[0];
