"./adventure-ui.js":function(module,exports,require){
'use strict';
const {escapeHTML:e}=require('./util.js');
const V=require('./play-ui.js');
function render(w) {
  const x=require('./adventure.js').visible(w);
  if(!x)return '<section class="panel empty">진행 중인 탐험이 없습니다. 이야기에서 장소에 들어가면 기록이 시작됩니다.</section>';
  return '<section class="panel"><small>'+e(x.name)+'</small><h2>'+e(x.nodeName)+'</h2><p>'+e(x.description)+'</p>'+V.facts([['방문한 장소',x.visited+'곳'],['진행',x.complete?'목적지 해결':'탐험 중']])+
    '<h3 class="spaced">눈앞의 길</h3><div class="play-paths">'+x.exits.map(n=>'<div><b>'+e(n.name)+'</b><small>'+e(n.blocked?'장치로 막힘':n.visited?'지나온 길':'아직 가보지 않은 곳')+'</small></div>').join('')+'</div>'+
    (x.mechanism?'<h3 class="spaced">장치</h3><p>'+e(x.mechanism.description)+'</p><span class="tag">'+(x.mechanism.solved?'조작 완료':'미해결')+'</span>':'')+
    (x.clues.length?'<h3 class="spaced">발견한 단서</h3><ul>'+x.clues.map(c=>'<li>'+e(c)+'</li>').join('')+'</ul>':'')+
    (x.resource?'<h3 class="spaced">채집원</h3>'+V.facts([[x.resource.name,'남은 수량 '+x.resource.remaining]]):'')+
    (x.encounter?'<h3 class="spaced">발견한 상대</h3>'+V.facts(x.encounter.enemies.map(a=>[a.name,'HP '+a.hp])):'')+
    '<h3 class="spaced">지나온 지도</h3>'+x.map.map(n=>'<div class="play-list-row"><b>'+e(n.name)+(n.current?' · 현재':'')+'</b><span>'+e(n.paths.join(' ↔ '))+'</span></div>').join('')+'</section>';
}
function presentation(w,entry) {
  const saved=entry.result,r=saved.result,x=r.exploration,rows=(r.changes||[]).map(c=>[c.label,c.value]);
  if(x){rows.push(['현재 위치',x.nodeName]);for(const c of x.clues)rows.push(['발견한 단서',c]);if(x.exits.length)rows.push(['보이는 길',x.exits.map(n=>n.name+(n.blocked?' (막힘)':'')).join(' · ')]);}
  return {cards:[{social:true,actor:w.actors[r.actorId]?.name||'',side:'탐험',label:r.action.name,roll:saved.roll,target:r.target,outcome:saved.outcome,reason:r.reason,socialChanges:rows}],turns:null,receipts:[]};
}
module.exports={render,presentation};

},
