      paint('.urpgdice-result','color:'+result+';font:700 30px/1.3 '+(murim?'Batang,serif':'"Malgun Gothic",sans-serif')+';letter-spacing:-1px');
      if(card.classList.contains('urpgdice-auto'))paint('.urpgdice-result','font-size:23px');
