const LABELS={commander:'지휘관 모드',action:'행동 모드',turnTable:'턴테이블',fastCombat:'전투가 길어',resultsOnly:'결과만',partyXP:'경험치 공유',halfEnemyHP:'적 체력 감소',oneChance:'한 번의 기회',noGameOver:'게임오버는 없어'};
