      if(!resumeInterrupted || next.sourceHash!==old.sourceHash)delete next.semantic.checkpoints;
      if(next.sourceHash===old.sourceHash)for(const key of ["actorManifest","discoveryComplete","discoveryPending","discoveryCompletedBatches"])if(old[key]!==undefined)next[key]=clone(old[key]);
