const Rules=require('./rules.js');
const Growth=require('./skill-growth.js');
const N=require('./native-rpg.js');
const CATEGORIES={equipment:'장비',consumable:'소모품',material:'재료',ammo:'탄약',quest:'퀘스트 물품'};
const KINDS={attack:'공격',heal:'회복',defense:'피해 경감',evasion:'회피',utility:'보조'};
const RARITIES={Normal:'노말',Rare:'레어',Unique:'유니크',Epic:'에픽',Legendary:'레전더리'};
const SLOTS={right_hand:'오른손',left_hand:'왼손',head:'머리',armor:'갑옷',waist:'허리',shoes:'신발',gloves:'장갑',accessory_1:'장신구 1',accessory_2:'장신구 2'};
