const options=(values,v)=>Object.entries(v!==undefined&&v!==''&&!Object.hasOwn(values,v)?{[v]:String(v)+' (현재 값)',...values}:values).map(([id,label])=>'<option value="'+e(id)+'" '+(String(id)===String(v)?'selected':'')+'>'+e(label)+'</option>').join('');
