const input=(key,label,v,type='number',extra='')=>'<label>'+e(label)+'<input data-fx-field="'+key+'" type="'+type+'" value="'+e(v??'')+'" '+(type==='number'?'step="any" ':'maxlength="300" ')+extra+'></label>';
