"./engine-contract.js":function(module,exports,require){
'use strict';

function engineContradictions(profile) {
  const issues = [];
  // Narrow guard for a common model error: the canonical decision claims that
  // the engine's low-roll fatal band is a critical-success band (or vice versa).
  // This does not attempt general semantic validation of arbitrary prose.
  const p = profile?.d100;
  if (!p) return issues;
  const low = new RegExp('1\\s*[~–—-]\\s*' + p.fatalMax + '(?!\\d)[^,;。\\n]{0,35}(?:대성공|critical\\s+success)', 'i');
  const high = new RegExp(p.perfectMin + '\\s*[~–—-]\\s*100[^,;。\\n]{0,35}(?:대실패|fumble|critical\\s+failure)', 'i');
  for (const [key, value] of Object.entries(profile.decisions || {})) {
    if ((low.test(value) || high.test(value)) && !/아니|아닙|않|not\b/i.test(value)) issues.push({
      path:'ruleDraft.decisions.' + key,
      message:'판정 설명의 대성공·대실패 방향이 실제 엔진과 반대입니다.',
      actual:'이 엔진은 주사위가 목표값보다 커야 성공합니다. 대실패는 1~' + p.fatalMax + ', 대성공은 ' + p.perfectMin + '~100입니다.',
      value
    });
  }
  return issues;
}
module.exports = {engineContradictions};

},
