  if(!extraTarget)a.uses[s.id]=R.num(a.uses[s.id])+1;
  if(optionalAmmo)require('./optional-feature-combat.js').consumeAmmo(w,a,s,changes,mod.ammoSaving>0&&d100(rng)<=mod.ammoSaving);
