  if(ui.nativeSkillEditor&&editingActor){const editor=SkillEditor.render(ui,ui.info.state,editingActor,ui.nativeSkillEditor.skillId);if(editor)return '<section class="panel">'+selector(ui,editingActor)+'</section>'+editor;}
