function capture(ui){const x=ui.reviewEditor;if(!x)return;if(!x)return;for(const el of document.querySelectorAll('[data-review-field]')){const s=at(x.schema,el.dataset.reviewField);let value=el.type==='checkbox'?el.checked:el.type==='number'?(el.value===''?undefined:Number(el.value)):el.dataset.reviewJson?parseJSON(el.value):el.value;if(s.enum&&s.type==='number')value=Number(value);if(el.dataset.reviewOptional&&typeof value==='string'&&!value.trim())value=undefined;put(x.args,el.dataset.reviewField,value);}}
