  const engineIssue = engineContradictions(p)[0];
  assert(!engineIssue, 'ENGINE_RULE_MISMATCH', engineIssue?.message, engineIssue);
  assert(p.d100.minTarget <= p.d100.maxTarget && p.d100.fatalMax <= p.d100.minTarget && p.d100.perfectMin > p.d100.maxTarget, 'INVALID_POLICY', '목표값과 대성공·대실패 경계가 모순됩니다.');
  assert(p.progression.thresholds.length === 5 && p.progression.thresholds.every((x, i, a) => !i || x > a[i - 1]) && p.progression.uses.length === 6, 'INVALID_POLICY', '숙련도 성장표는 증가하는 다섯 단계와 여섯 횟수 값이 필요합니다.');
  assert(p.exploration.mainPath <= p.exploration.totalNodes && p.exploration.totalNodes - p.exploration.mainPath <= p.exploration.branches * p.exploration.branchDepth, 'INVALID_POLICY', '탐험 길이·분기 예산이 맞지 않습니다.');
  assert(new Set(p.rules.damageOrder).size === p.rules.damageOrder.length && p.rules.damageOrder.includes('vital'), 'INVALID_POLICY', '피해 적용 순서를 확인하세요.');
