// versus Rare M0 x1.2. Integer counts, durations and caps can produce ties.
const RANK_FACTORS=[1,1.2,1.4,1.6,1.8];
const CHANNELS=['amount','accuracy','efficiency','uses','status','duration'];
const LABELS={amount:'효과량',accuracy:'명중',efficiency:'비용 절감',uses:'사용 횟수',status:'상태 효과',duration:'지속 시간'};
