    const found=people.find(a=>a.id===target.id)||people.find(a=>[a.name,...(Array.isArray(a.aliases)?a.aliases:[])].some(name=>norm(name)===norm(target.name)))||(roster.length===1&&people.length===1?people[0]:null);
