  if(args.combat)data={...data,type:'combat'};
  assert(['social','conversation','task','forced','training','recovery','rest','advance_day','gift','combat'].includes(data.type),'SOCIAL_INTERPRETATION','보조 AI가 행동 분류를 반환하지 않았습니다.');
  const purpose=text(data.purpose)||text(args.intent)||args.action;
  const type=data.type||'conversation',stat=statKey(data.stat,bookId,bookId==='romance'?'expression':'speech');
  const actionId=fixed?.id||'social.v4.'+(await hash({actorId,targetId,purpose:norm(purpose),type,stat})).slice(0,24);
  const saved=actions.find(a=>a.id===actionId);
  const action=Books.normalizeAction(saved||{...data,id:actionId,name:text(data.name)||args.action,purpose,stat,opposedStat:statKey(data.opposedStat,bookId,bookId==='romance'?'will':'care'),proposal:data.proposal?{...object(data.proposal),targetId:targetId||''}:undefined},bookId);
