  const s=w.meta.social,settings=w.meta.rulebook.settings,stamina=s.stamina[a.id];
  const cost=definition.type==='rest'?0:settings.actionStamina;
  if(definition.type==='training')assert(stamina.current>=cost,'NO_STAMINA','훈련할 체력이 부족합니다. 식사·음료·휴식으로 회복하세요.');
  stamina.current=change(changes,'stamina',a.id,'current',stamina.current,Math.max(0,stamina.current-cost));
