  const onceKey=definition.type==='training'?'training:'+s.day+':'+a.id+'>'+definition.stat:definition.type+':'+s.day+':'+a.id+'>'+String(t?.id||'self')+'>'+(definition.type==='recovery'?'recovery':definition.id);
