  const proposalAction=['social','gift'].includes(definition.type),oldAttempt=proposalAction?s.attempts[eventKey]:null;
  const fresh=!oldAttempt || oldAttempt.lastDay!==s.day && (id!=='dating' || oldAttempt.failures===0);
  const attempts=fresh?0:oldAttempt.attempts,streak=fresh?0:oldAttempt.failures;
  let repetition=null;
