    if(old?.active===false&&record.active===true){a.active=true;rows.push({kind:'registered',actorId:a.id,key:'인물 재등장',before:0,after:1,delta:1});}
    a.aliases=[...new Set([...a.aliases,...(record.aliases||[])])].slice(0,30);
    if(!old)rows.push({kind:'registered',actorId:a.id,key:'인물 등록',before:0,after:1,delta:1,stats:clone(a.raw)});
