    difficulty:['easy','normal','hard'].includes(input.difficulty)?input.difficulty:'normal',
    aliases:[...new Set((Array.isArray(input.aliases)?input.aliases:[]).map(v=>text(v,200)).filter(Boolean))].slice(0,30),
    purpose:text(input.purpose,300)||input.id,morality:['good','evil','neutral'].includes(input.morality)?input.morality:'neutral',
