  const text={type:'string',minLength:1,maxLength:3000},properties={name:{...text,description:'등록된 소환수 ID 또는 최초 등록할 이름'},owner:{...text,description:'소환자의 저장 ID'},description:{type:'string',maxLength:6000},instanceKey:text,lifetime:{type:'string',enum:Object.keys(S.LIFETIMES)},duration:{type:'number',minimum:1,maximum:1000000},growth:{type:'string',enum:['fixed','independent']},shareXP:{type:'boolean'},limit:{type:'integer',minimum:1,maximum:100},costResource:{type:'string',maxLength:300},cost:{type:'number',minimum:0,maximum:1e9},mode:{type:'string',enum:['cast','permanent']}};
