  const call={op:'ensure_actor',actionId:args.actionId,name:args.name,kind:'summon',description:(args.description||'')+'\n소환수로 사용할 독립 인물입니다. 해당 룰북의 체력·능력치·기술·효과를 준비하고, 다른 인물의 수치나 성장 상태를 덮어쓰지 마세요.'};
  if(schema.properties.owner)call.owner=owner.id;if(args.instanceKey&&schema.properties.instanceKey){call.instanceKey=args.instanceKey;if(schema.properties.newInstance)call.newInstance=true;}
